-- challenge chal_quiz_sqlf_111 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_sqlf_111', (SELECT id FROM catalog.course WHERE public_id = 'sql-data-analysis-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'sql-data-analysis-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-sqlf-1-1' AND is_deleted = false LIMIT 1), 'where-precedence-clause-order-quiz', 'Read the query the way SQLite reads it', 'Two questions from the spring coupon incident: how AND and OR group without parentheses, and what the logical order of the clauses lets each clause see.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_111'), 'The orders table has seven rows (order_id, status, coupon_code):

101  paid       SPRING10
102  refunded   SPRING10
103  paid       SPRING20
104  cancelled  SPRING20
105  pending    SPRING10
106  paid       NULL
107  paid       WELCOME5

A colleague moved the status check to the end:

SELECT order_id FROM orders
WHERE coupon_code = ''SPRING10'' OR coupon_code = ''SPRING20'' AND status = ''paid'';

Which rows does it return?', 'single_choice'::question_type, 'AND binds tighter than OR, wherever it appears. SQLite reads the condition as coupon_code = ''SPRING10'' OR (coupon_code = ''SPRING20'' AND status = ''paid''). The first branch keeps every SPRING10 order, whatever its status (101, 102, 105); the second keeps only the paid SPRING20 order (103). Moving the status check to the end did not fix the bug, it only moved it to the other coupon. Mixing AND and OR without parentheses is allowed, which is exactly why it is dangerous. The query that was meant: status = ''paid'' AND coupon_code IN (''SPRING10'', ''SPRING20''), which returns 101 and 103.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('101 and 103 (the paid orders with a spring coupon)', false),
        ('101, 102, 103 and 105', true),
        ('101, 102, 103, 104 and 105 (every spring coupon order)', false),
        ('None: mixing AND and OR without parentheses is an error', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_111'), 'Look at this query on Beanbox''s orders table:

SELECT DISTINCT customer_id AS buyer
FROM orders
WHERE status = ''paid''
ORDER BY buyer
LIMIT 3;

Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'The logical order is FROM, WHERE, GROUP BY, HAVING, SELECT (with DISTINCT), ORDER BY, LIMIT. ORDER BY runs after SELECT, so it can use the alias buyer. DISTINCT is part of the SELECT step, so duplicates are removed before LIMIT counts rows: the result is the three smallest distinct customer ids with a paid order. LIMIT is the very last step, so it never picks rows before the sort. WHERE runs before SELECT, so the alias does not exist there yet: standard SQL and PostgreSQL reject WHERE buyer > 10 (SQLite accepts it as an extension, which is why it is not portable). BETWEEN is inclusive at both ends, so BETWEEN 2000 AND 3000 keeps an order of exactly 3000 cents.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('ORDER BY buyer works because ORDER BY runs after SELECT, where the alias is created.', true),
        ('LIMIT 3 runs before ORDER BY, so you get three arbitrary customers and then they are sorted.', false),
        ('DISTINCT removes duplicate customers before LIMIT counts rows, so the three rows are three different customers.', true),
        ('Replacing the WHERE line with WHERE buyer > 10 is portable: PostgreSQL accepts it too.', false),
        ('In the same table, WHERE total_cents BETWEEN 2000 AND 3000 keeps an order of exactly 3000 cents.', true)
    ) AS o(option_text, is_correct);

