-- challenge chal_quiz_sqlf_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_sqlf_131', (SELECT id FROM catalog.course WHERE public_id = 'sql-data-analysis-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'sql-data-analysis-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-sqlf-1-3' AND is_deleted = false LIMIT 1), 'nulls-three-valued-logic-quiz', 'Predict what NULL does to a filter', 'Count the rows four NULL-sensitive filters keep on a small customers table, then pick the expressions that evaluate to UNKNOWN.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_131'), 'The customers table has 11 rows. Their referral_source values are:

''ads'', ''friend'', NULL, ''search'', ''ads'', ''friend'', NULL, ''friend'', ''ads'', NULL, ''search''

How many rows does SELECT COUNT(*) FROM customers WHERE ... return for each of these filters, in this order?

(a) referral_source <> ''ads''
(b) NOT (referral_source = ''ads'')
(c) referral_source NOT IN (''ads'', NULL)
(d) referral_source IS NOT ''ads''', 'single_choice'::question_type, 'There are 3 ''ads'' rows, 5 rows with another source and 3 NULL rows. (a) For a NULL row, NULL <> ''ads'' is UNKNOWN, and WHERE keeps only TRUE, so only the 5 known non-ads rows remain. (b) NOT of UNKNOWN is still UNKNOWN, so rewriting the test with NOT changes nothing: 5. (c) x NOT IN (''ads'', NULL) means x <> ''ads'' AND x <> NULL. The second part is UNKNOWN for every row, so the whole condition is FALSE (for ''ads'') or UNKNOWN (for everything else) and never TRUE: 0 rows. (d) IS NOT is SQLite''s null-safe comparison (IS DISTINCT FROM in standard SQL and PostgreSQL): NULL IS NOT ''ads'' is TRUE, so the 5 known rows and the 3 NULL rows are kept: 8.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('(a) 5, (b) 5, (c) 0, (d) 8', true),
        ('(a) 8, (b) 8, (c) 8, (d) 8', false),
        ('(a) 5, (b) 8, (c) 0, (d) 8', false),
        ('(a) 5, (b) 5, (c) 5, (d) 8', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_131'), 'Which of these expressions evaluate to UNKNOWN (SQLite returns NULL for UNKNOWN)? (Select all that apply.)', 'multiple_choice'::question_type, 'A comparison with =, <>, <, > is UNKNOWN as soon as one side is NULL, even NULL <> NULL: two unknown values are not known to be different. NOT UNKNOWN stays UNKNOWN, so NOT (NULL = ''ads'') is UNKNOWN too. ''search'' NOT IN (''ads'', ''friend'', NULL) expands to ''search'' <> ''ads'' AND ''search'' <> ''friend'' AND ''search'' <> NULL, which is TRUE AND TRUE AND UNKNOWN = UNKNOWN. The others have a definite answer: IS NOT is SQLite''s null-safe comparison, so NULL IS NOT ''friend'' is TRUE; FALSE AND anything is FALSE; TRUE OR anything is TRUE (1 = 1 is TRUE); and ''friend'' IN (''ads'', ''friend'', NULL) is TRUE because one comparison already matched, and TRUE OR UNKNOWN is TRUE.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('NULL <> NULL', true),
        ('NULL IS NOT ''friend''', false),
        ('FALSE AND NULL', false),
        ('1 = 1 OR NULL', false),
        ('NOT (NULL = ''ads'')', true),
        ('''friend'' IN (''ads'', ''friend'', NULL)', false),
        ('''search'' NOT IN (''ads'', ''friend'', NULL)', true)
    ) AS o(option_text, is_correct);

