ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_141'), 'The orders table has six rows with these ordered_at values (TEXT, UTC):

''2026-02-28 23:59:59''
''2026-03-01 00:00:00''
''2026-03-14 12:30:00''
''2026-03-31 00:00:00''
''2026-03-31 18:45:10''
''2026-04-01 00:00:00''

How many rows does this query count in SQLite?

SELECT COUNT(*) FROM orders
WHERE ordered_at BETWEEN ''2026-03-01'' AND ''2026-03-31'';', 'single_choice'::question_type, 'BETWEEN a AND b means ordered_at >= a AND ordered_at <= b, and both sides are TEXT, so SQLite compares them character by character. ''2026-03-01 00:00:00'' starts with ''2026-03-01'' and is longer, so it is greater than ''2026-03-01'': kept. ''2026-03-14 12:30:00'' is between the bounds: kept. Both 31 March rows start with ''2026-03-31'' and are longer, so they are greater than ''2026-03-31'' and fail the <= test - even the one at exactly midnight. February 28 and April 1 are outside. Result: 2 rows, and every 31 March order is lost. The half-open range ordered_at >= ''2026-03-01'' AND ordered_at < ''2026-04-01'' keeps all four March rows.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_141') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('2', true),
        ('3', false),
        ('4', false),
        ('5', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_141'), 'In May, the orders table has exactly three orders: (status ''paid'', total_cents 2500), (''paid'', 4000) and (''cancelled'', 1800). What does this query return?

SELECT SUM(CASE WHEN status = ''refunded'' THEN total_cents END)        AS refunded_cents,
       COUNT(CASE WHEN status = ''refunded'' THEN 1 END)                AS refunds,
       SUM(CASE WHEN status = ''paid'' THEN total_cents ELSE 0 END)     AS paid_cents
FROM orders;', 'single_choice'::question_type, 'A CASE without ELSE returns NULL when no WHEN matches. No order is refunded, so the first CASE is NULL on all three rows, and SUM over only NULLs is NULL, not 0. COUNT(expression) counts the non-NULL values, and there are none, so COUNT returns 0 - COUNT never returns NULL. The third CASE has ELSE 0, so it adds 2500 + 4000 + 0 = 6500. This is why conditional sums in a report always get ELSE 0: a NULL cell breaks totals and comparisons further down (NULL + 6500 is NULL).', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_141') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
