        ('refunded_cents 0, refunds 0, paid_cents 6500', false),
        ('refunded_cents NULL, refunds NULL, paid_cents 6500', false),
        ('refunded_cents 0, refunds 0, paid_cents 8300', false)
    ) AS o(option_text, is_correct);

