-- challenge chal_quiz_sqlf_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_sqlf_211', (SELECT id FROM catalog.course WHERE public_id = 'sql-data-analysis-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'sql-data-analysis-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-sqlf-2-1' AND is_deleted = false LIMIT 1), 'join-fan-out-quiz', 'Count the rows before you trust the sum', 'Two small joins from the revenue incident: predict how many rows a join of orders, payments and order items produces and what SUM(total_cents) returns, then pick the queries that give finance''s revenue number.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_211'), 'Three orders: order 1 (total_cents 3000), order 2 (2000) and order 3 (1500).
payments: order 1 has 2 rows, order 2 has 1 row, order 3 has none yet.
order_items: order 1 has 3 rows, order 2 has 2 rows, order 3 has 1 row.

SELECT COUNT(*), SUM(o.total_cents)
FROM orders o
JOIN payments    p ON p.order_id = o.order_id
JOIN order_items i ON i.order_id = o.order_id;

What does it return?', 'single_choice'::question_type, 'A join produces one row for every combination of rows that match. For order 1 that is 2 payments x 3 items = 6 rows, for order 2 it is 1 x 2 = 2 rows, and order 3 has no payment, so the inner join drops it: 8 rows. SUM(o.total_cents) then adds each order total once per row: 6 x 3000 + 2 x 2000 = 22000, while the two orders that have a payment are only worth 5000. Two one-to-many joins from the same table multiply, they do not add.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('8 rows, 22000', true),
        ('3 rows, 6500', false),
        ('8 rows, 5000', false),
        ('9 rows, 6500', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_211'), 'orders (all status ''paid''): order 201 total 4500, order 202 total 4500, order 203 total 7000.
payments: order 201 one payment of 4500, order 202 two payments (2000 + 2500), order 203 one payment of 7000.

Finance wants the total of all orders that have at least one payment: 16000 cents. Which queries return 16000? (Select all that apply.)', 'multiple_choice'::question_type, 'A plain JOIN to payments repeats order 202 for each of its two payments, so SUM(o.total_cents) gives 20500; a LEFT JOIN keeps unmatched orders but fans out exactly the same way, so it also gives 20500. SUM(DISTINCT o.total_cents) removes repeated values, not repeated orders: orders 201 and 202 both total 4500, so it returns 4500 + 7000 = 11500. Pre-aggregating payments to one row per order before the join keeps one row per order (16000), and IN only tests whether an order has a payment, so it never repeats an order (16000).', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('SELECT SUM(o.total_cents) FROM orders o JOIN payments p ON p.order_id = o.order_id', false),
        ('SELECT SUM(DISTINCT o.total_cents) FROM orders o JOIN payments p ON p.order_id = o.order_id', false),
        ('SELECT SUM(o.total_cents) FROM orders o JOIN (SELECT order_id, SUM(amount_cents) AS paid_cents FROM payments GROUP BY order_id) AS p ON p.order_id = o.order_id', true),
        ('SELECT SUM(total_cents) FROM orders WHERE order_id IN (SELECT order_id FROM payments)', true),
        ('SELECT SUM(o.total_cents) FROM orders o LEFT JOIN payments p ON p.order_id = o.order_id', false)
    ) AS o(option_text, is_correct);

