-- challenge chal_quiz_sqlf_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_sqlf_311', (SELECT id FROM catalog.course WHERE public_id = 'sql-data-analysis-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'sql-data-analysis-foundations') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-sqlf-3-1' AND is_deleted = false LIMIT 1), 'ranking-ties-and-frames-quiz', 'Ties in rankings and running totals', 'Two small tables with ties: predict what ROW_NUMBER, RANK and DENSE_RANK return, and what a running SUM with the default window frame adds up when several rows share the same ORDER BY value.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_311'), 'Five products and their revenue:

A 900, B 700, C 700, D 500, E 300

Each row gets ROW_NUMBER() OVER (ORDER BY revenue DESC, name), RANK() OVER (ORDER BY revenue DESC) and DENSE_RANK() OVER (ORDER BY revenue DESC). Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'B and C tie at 700. ROW_NUMBER never repeats a number, so they get 2 and 3 (the name decides who is first). RANK gives both 2 and then skips: D is 4, because three products have a higher revenue. DENSE_RANK gives both 2 and does not skip: D is 3, E is 4. So a filter rank <= 3 keeps A, B, C (3 rows: there is no rank 3), and dense_rank <= 3 keeps A, B, C and D (4 rows). For a top-N slide, decide first what a tie at the cut-off should do, then pick the function.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('D gets RANK 4.', true),
        ('D gets DENSE_RANK 3.', true),
        ('B and C get the same ROW_NUMBER.', false),
        ('WHERE rank <= 3 keeps 4 rows.', false),
        ('WHERE dense_rank <= 3 keeps 4 rows.', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_311'), 'A small table sales, one row per order:

id  day    amount
1   03-01  100
2   03-01   50
3   03-02  200
4   03-02   30
5   03-03   20

SELECT id, SUM(amount) OVER (ORDER BY day) AS to_date FROM sales ORDER BY id;

What is to_date for ids 1 to 5?', 'single_choice'::question_type, 'With ORDER BY and no frame clause, the frame is RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW. RANGE works on values, not rows: the current row''s peers (every row with the same day) are all inside the frame. So both 03-01 rows get 100 + 50 = 150, both 03-02 rows get 150 + 230 = 380, and 03-03 gets 400. 100, 150, 350, 380, 400 is what ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW gives with ORDER BY day, id. To get one point per day, aggregate per day first, then run the window over the daily rows.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_311') AND order_index = 2)
    RETURNING id
)
