-- challenge chal_quiz_sqlf_331 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_sqlf_331', (SELECT id FROM catalog.course WHERE public_id = 'sql-data-analysis-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'sql-data-analysis-foundations') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-sqlf-3-3' AND is_deleted = false LIMIT 1), 'sanity-checks-quiz', 'Which check catches it?', 'Run the lesson''s sanity checks in your head on a broken report, then decide what really happens when a value is pasted into SQL with an f-string.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_331'), 'A second analyst "fixes" the incident report by dividing each country by the report''s own total instead of finance''s total. The new report for Q1 2026 is:

VN    67000 cents   47.9 %
DE    30000 cents   21.4 %
US    25000 cents   17.9 %
vn    18000 cents   12.9 %   (the country is ''vn '')

The independent total of paid Q1 orders is 125000 cents, and the countries with paid Q1 orders are VN, DE and US (after trimming and upper-casing). Which checks from this lesson FAIL? (Select all that apply.)', 'multiple_choice'::question_type, 'The parts add up to 67000 + 30000 + 25000 + 18000 = 140000 cents, not 125000, so the reconcile check fails: the join still fans out. ''VN'' and ''vn '' have the same key once spaces are trimmed and the text is upper-cased, so the grain check fails too. The percentages now add up to 100.1, which is within 0.5 of 100, and every one of them is between 0 and 100, so both range checks pass, and every expected country has a row. That is the lesson of this question: percentages computed from the report''s own total always add up to about 100, even when every number is wrong. Only a total computed by a second, independent query catches the fan-out.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_331') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Reconcile: the parts do not add up to the independent total.', true),
        ('Grain: two rows have the same key.', true),
        ('Percent sum: the percentages are more than 0.5 away from 100.', false),
        ('Percent range: a percentage is below 0 or above 100.', false),
        ('Completeness: a country with paid orders has no row.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_331'), 'The customers table has 5 rows, and no customer''s country is ''x''. A report script reads a country from a web form, and a visitor types:

x'' OR 1=1 --

What do these two lines return?

(A) db.execute(f"SELECT COUNT(*) FROM customers WHERE country = ''{country}''").fetchone()
(B) db.execute("SELECT COUNT(*) FROM customers WHERE country = ?", (country,)).fetchone()', 'single_choice'::question_type, 'In (A) the text is pasted into the SQL before SQLite reads it, so the database receives WHERE country = ''x'' OR 1=1 --''. The quote closes the string, OR 1=1 is true for every row, and -- turns the leftover quote into a comment: the query counts all 5 customers. That is SQL injection: input that changes the meaning of the query. In (B) the SQL text never changes; the driver sends the value separately and SQLite compares it as one string, so it looks for a customer whose country is literally "x'' OR 1=1 --" and finds none: (0,). Placeholders work for values only; table and column names cannot be parameters.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sqlf_331') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('(A) returns (5,), (B) returns (0,).', true),
        ('Both return (0,): no country is equal to that text.', false),
        ('(A) raises a syntax error, (B) returns (0,).', false),
        ('Both return (5,): the ? placeholder pastes the text in the same way.', false)
    ) AS o(option_text, is_correct);

